CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, open_id VARCHAR(128) NOT NULL UNIQUE, experience VARCHAR(24) NOT NULL DEFAULT '', `active` BIGINT UNSIGNED NOT NULL DEFAULT 0, expires DATETIME(3) NULL);
CREATE TABLE IF NOT EXISTS exercises (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, muscle VARCHAR(255) NOT NULL, equipment VARCHAR(255) NOT NULL, guide TEXT NOT NULL, setup TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `owner` BIGINT UNSIGNED NOT NULL, name VARCHAR(255) NOT NULL, `days` JSON NULL, published BOOLEAN NOT NULL DEFAULT FALSE, revision BIGINT UNSIGNED NOT NULL, INDEX(`owner`,published));
CREATE TABLE IF NOT EXISTS template_drafts (id BIGINT UNSIGNED PRIMARY KEY, name VARCHAR(255) NOT NULL, `days` JSON NULL);
CREATE TABLE IF NOT EXISTS sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `owner` BIGINT UNSIGNED NOT NULL, plan_id BIGINT UNSIGNED NOT NULL, `day` JSON NOT NULL, done JSON NOT NULL, weights JSON NULL, started DATETIME(3) NOT NULL, ended DATETIME(3) NULL, INDEX(`owner`,ended,id));
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(32) PRIMARY KEY, `owner` BIGINT UNSIGNED NOT NULL, product VARCHAR(128) NOT NULL, `days` INT NOT NULL, price INT NOT NULL, `status` VARCHAR(32) NOT NULL, platform VARCHAR(96) UNIQUE, refund_id VARCHAR(96) UNIQUE, created_at DATETIME(3) NOT NULL, INDEX(`owner`,created_at), INDEX(`status`,created_at));
CREATE TABLE IF NOT EXISTS `grants` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, `days` INT NOT NULL, reason TEXT NOT NULL, `operator` VARCHAR(128) NOT NULL, revoked DATETIME(3) NULL, created_at DATETIME(3) NOT NULL, INDEX(user_id,created_at));
CREATE TABLE IF NOT EXISTS products (`days` INT PRIMARY KEY, price INT NOT NULL, enabled BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS audits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(128) NOT NULL, `action` TEXT NOT NULL, `target` BIGINT UNSIGNED NOT NULL, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS feedbacks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `owner` BIGINT UNSIGNED NOT NULL, content VARCHAR(1000) NOT NULL, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS staffs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `login` VARCHAR(96) NOT NULL UNIQUE, `hash` VARCHAR(128) NOT NULL, `admin` BOOLEAN NOT NULL, enabled BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS staff_sessions (id VARCHAR(64) PRIMARY KEY, staff_id BIGINT UNSIGNED NOT NULL, `until` DATETIME(3) NOT NULL, INDEX(`until`));
